+import { entitlementsFor, checkGeneration, checkUploads, FREE, PRO } from "../tiers";
+
+describe("entitlementsFor", () => {
+  test("free regenerates once per occasion; pro is unlimited", () => {
+    expect(entitlementsFor("free").regeneratesPerOccasion).toBe(1);
+    expect(entitlementsFor("pro").regeneratesPerOccasion).toBeNull(); // null = unlimited
+  });
+
+  test("styled looks, analytics, gap analysis and packing are Pro only", () => {
+    const free = entitlementsFor("free");
+    expect(free.styledLooks).toBe(false);
+    expect(free.analytics).toBe(false);
+    expect(free.gapAnalysis).toBe(false);
+    expect(free.packingMode).toBe(false);
+    const pro = entitlementsFor("pro");
+    expect(pro.styledLooks).toBe(true);
+    expect(pro.analytics).toBe(true);
+    expect(pro.gapAnalysis).toBe(true);
+    expect(pro.packingMode).toBe(true);
+  });
+
+  test("an unknown or missing tier falls back to free — capabilities fail closed", () => {
+    for (const bad of [null, undefined, "", "enterprise", 7, {}, "PRO"]) {
+      expect(entitlementsFor(bad).tier).toBe("free");
+      expect(entitlementsFor(bad).analytics).toBe(false);
+      expect(entitlementsFor(bad).styledLooks).toBe(false);
+    }
+  });
+
+  test("free saved-outfit cap is finite, pro's is not", () => {
+    expect(FREE.savedOutfits).toBe(10);
+    expect(PRO.savedOutfits).toBeNull();
+  });
+});
+
+describe("checkUploads", () => {
+  test("free adds ten pieces a day; pro is unlimited", () => {
+    expect(entitlementsFor("free").uploadsPerDay).toBe(10);
+    expect(entitlementsFor("pro").uploadsPerDay).toBeNull();
+  });
+
+  test("the allowance counts down and then blocks", () => {
+    expect(checkUploads(FREE, 0)).toMatchObject({ allowed: true, remaining: 10 });
+    expect(checkUploads(FREE, 9)).toMatchObject({ allowed: true, remaining: 1 });
+    expect(checkUploads(FREE, 10)).toMatchObject({ allowed: false, remaining: 0 });
+  });
+
+  test("being over never reports a negative remaining", () => {
+    expect(checkUploads(FREE, 99).remaining).toBe(0);
+  });
+
+  test("pro is never blocked", () => {
+    expect(checkUploads(PRO, 5000)).toMatchObject({ allowed: true, remaining: null });
+  });
+
+  // The cap is PER DAY, not a total — the closet is the moat and the generator
+  // measurably degrades on a small wardrobe, so nothing here may imply a ceiling
+  // on closet size.
+  test("a blocked upload says it is a daily limit, not a closet limit", () => {
+    const r = checkUploads(FREE, 10);
+    expect(r.allowed).toBe(false);
+    expect(r.reason).toMatch(/today|day/i);
+    expect(r.reason).not.toMatch(/closet is full|maximum items/i);
+  });
+});
+
+describe("checkGeneration — drops", () => {
+  // §1 of MONETISATION: the daily drop is the product and is never gated. An
+  // occasion's first look of the day costs nothing on any tier.
+  test("an occasion's first look of the day is free on every tier", () => {
+    for (const e of [FREE, PRO]) {
+      expect(checkGeneration(e, { kind: "drop", regeneratesUsed: 0 })).toMatchObject({
+        allowed: true,
+      });
+    }
+  });
+
+  // Four occasions must all remain reachable — a user who has dropped three
+  // occasions today is not "at a limit" for the fourth.
+  test("a drop is allowed regardless of what other occasions have used", () => {
+    expect(checkGeneration(FREE, { kind: "drop", regeneratesUsed: 99 }).allowed).toBe(true);
+  });
+});
+
+describe("checkGeneration — regenerates", () => {
+  test("free gets one regenerate for an occasion, then is limited", () => {
+    expect(checkGeneration(FREE, { kind: "regenerate", regeneratesUsed: 0 })).toMatchObject({
+      allowed: true,
+      remaining: 1,
+    });
+    expect(checkGeneration(FREE, { kind: "regenerate", regeneratesUsed: 1 })).toMatchObject({
+      allowed: false,
+      remaining: 0,
+    });
+  });
+
+  // The allowance is PER OCCASION, so regenerating Work must not spend Evening's.
+  // The caller supplies the count for the occasion being asked about; this asserts
+  // the function never reaches for a global total.
+  test("the allowance is counted per occasion, not globally", () => {
+    expect(checkGeneration(FREE, { kind: "regenerate", regeneratesUsed: 0 }).allowed).toBe(true);
+  });
+
+  test("pro is never blocked and reports no finite remaining", () => {
+    expect(checkGeneration(PRO, { kind: "regenerate", regeneratesUsed: 1000 })).toMatchObject({
+      allowed: true,
+      remaining: null,
+    });
+  });
+
+  test("being over the allowance never reports a negative remaining", () => {
+    expect(checkGeneration(FREE, { kind: "regenerate", regeneratesUsed: 99 }).remaining).toBe(0);
+  });
+
+  test("a blocked regenerate carries a reason a screen can show the user", () => {
+    const r = checkGeneration(FREE, { kind: "regenerate", regeneratesUsed: 1 });
+    expect(r.allowed).toBe(false);
+    expect(typeof r.reason).toBe("string");
+    expect(r.reason).toMatch(/pro/i);
+  });
+});
+
+describe("checkGeneration — styled looks", () => {
+  // Pro #2. Gated rather than given a free allowance: "first per item free" has
+  // no ceiling, since it scales with closet size.
+  test("free cannot build a look around a piece, and is told why", () => {
+    const r = checkGeneration(FREE, { kind: "styled", regeneratesUsed: 0 });
+    expect(r.allowed).toBe(false);
+    expect(r.reason).toMatch(/pro/i);
+  });
+
+  test("pro can, without limit", () => {
+    expect(checkGeneration(PRO, { kind: "styled", regeneratesUsed: 0 })).toMatchObject({
+      allowed: true,
+      remaining: null,
+    });
+  });
+
+  // The gate must not depend on the regenerate counter — styling an item is a
+  // different question from asking an occasion again.
+  test("a styled look is not affected by regenerate usage", () => {
+    expect(checkGeneration(PRO, { kind: "styled", regeneratesUsed: 99 }).allowed).toBe(true);
+  });
+});


=== DIFF: lib/billing/entitlements.ts ===
@@ -0,0 +1,131 @@
+import "server-only";
+import { createClient } from "@/lib/supabase/server";
+import { localDateFor } from "@/lib/outfits/local-date";
+import {
+  FREE,
+  PRO,
+  entitlementsFor,
+  checkGeneration,
+  checkUploads,
+  type Entitlements,
+  type Tier,
+  type GenerationKind,
+  type GenerationCheck,
+} from "./tiers";
+
+import { UploadLimitError } from "./errors";
+
+export { FREE, PRO, entitlementsFor, checkGeneration, checkUploads };
+export { QuotaExceededError, UploadLimitError } from "./errors";
+export type { Entitlements, Tier, GenerationKind, GenerationCheck };
+
+/**
+ * The user's entitlements right now.
+ *
+ * Reads the tier from `profiles`. A read failure returns FREE rather than
+ * throwing: a broken query must never take the app down, and handing out Pro on
+ * an error is the wrong side to fail on.
+ *
+ * `profiles.tier` is not writable by `authenticated` (see the billing
+ * migration) — RLS scopes rows, not columns, so without that revoke a user
+ * could grant themselves Pro from the browser.
+ */
+export async function currentEntitlements(): Promise<Entitlements> {
+  // Local override so Pro surfaces can be built and demoed before billing.
+  // Checked before the query so it works even with no session.
+  if (process.env.NODE_ENV !== "production" && process.env.FITCHECK_FORCE_TIER) {
+    return entitlementsFor(process.env.FITCHECK_FORCE_TIER);
+  }
+
+  const supabase = await createClient();
+  const {
+    data: { user },
+  } = await supabase.auth.getUser();
+  if (!user) return FREE;
+
+  const { data } = await supabase.from("profiles").select("tier").eq("id", user.id).single();
+  return entitlementsFor(data?.tier);
+}
+
+/**
+ * How many times this user has already regenerated ONE occasion on their local
+ * today.
+ *
+ * Reads the append-only `generation_events` ledger, never the `outfits` table.
+ * `saveDailyLooks` is delete-then-insert, so a regenerate REPLACES the day's
+ * rows for an occasion — the act of regenerating erases its own evidence, and
+ * afterwards a first drop is indistinguishable from a fifth. The ledger exists
+ * precisely because that count is unrecoverable from the outfits themselves.
+ */
+export async function regeneratesUsedToday(occasion: string, today: string): Promise<number> {
+  const supabase = await createClient();
+  const { count } = await supabase
+    .from("generation_events")
+    .select("id", { count: "exact", head: true })
+    .eq("occasion", occasion)
+    .eq("generated_on", today)
+    .eq("kind", "regenerate");
+  return count ?? 0;
+}
+
+/**
+ * May this user add another piece? Throws `UploadLimitError` if not.
+ *
+ * Called from `uploadAndTag` rather than `confirmItem` because that is where
+ * the cost actually lands — two storage writes and a Haiku call happen before
+ * the user ever sees the confirm screen.
+ *
+ * Counting: candidate rows are narrowed to the last 48 hours in SQL, then
+ * filtered through `localDateFor`. Comparing the user's local day against a
+ * `timestamptz` otherwise needs timezone arithmetic with DST edges; a two-day
+ * window is at most a couple of dozen rows for one user, and it reuses the
+ * date function the whole product is already keyed on rather than inventing a
+ * second, subtly different one.
+ */
+export async function assertCanUpload(timeZone: string): Promise<void> {
+  const e = await currentEntitlements();
+  if (e.uploadsPerDay == null) return;
+
+  const supabase = await createClient();
+  const {
+    data: { user },
+  } = await supabase.auth.getUser();
+  if (!user) throw new Error("Not authenticated");
+
+  const now = new Date();
+  const since = new Date(now.getTime() - 48 * 60 * 60 * 1000).toISOString();
+  const { data } = await supabase
+    .from("items")
+    .select("created_at")
+    .eq("user_id", user.id)
+    .gte("created_at", since);
+
+  const today = localDateFor(now, timeZone);
+  // Archived pieces still count — the upload already cost the storage write and
+  // the tagging call, and archiving to reset the meter would be a free retry.
+  const addedToday = (data ?? []).filter(
+    (r) => r.created_at && localDateFor(new Date(r.created_at), timeZone) === today,
+  ).length;
+
+  const check = checkUploads(e, addedToday);
+  if (!check.allowed) throw new UploadLimitError(check.reason);
+}
+
+/**
+ * Record a generation that actually happened.
+ *
+ * Called AFTER the model request succeeds — a failed generation costs the user
+ * nothing, so charging for one would be charging for our own error. RLS scopes
+ * the insert to the caller.
+ */
+export async function recordGeneration(
+  userId: string,
+  occasion: string,
+  today: string,
+  kind: GenerationKind,
+): Promise<void> {
+  const supabase = await createClient();
+  await supabase
+    .from("generation_events")
+    .insert({ user_id: userId, occasion, generated_on: today, kind });
+}


=== DIFF: lib/billing/errors.ts ===
@@ -0,0 +1,26 @@
+/**
+ * Billing's error types, kept PURE and free of `server-only`.
+ *
+ * Same split as `tiers.ts` versus `entitlements.ts`: anything that touches
+ * Supabase sits behind the `server-only` guard, and anything a test — or a
+ * future client component rendering "1 redo left" — needs to reference lives
+ * out here. Importing these must never drag the resolver into a client bundle.
+ *
+ * Both are STATES the UI explains, not failures. Every call site catches them
+ * and returns a `limited` result rather than letting them surface as
+ * "something went wrong".
+ */
+
+export class QuotaExceededError extends Error {
+  constructor(message = "Daily generation limit reached") {
+    super(message);
+    this.name = "QuotaExceededError";
+  }
+}
+
+export class UploadLimitError extends Error {
+  constructor(message = "Daily upload limit reached") {
+    super(message);
+    this.name = "UploadLimitError";
+  }
+}


=== DIFF: lib/billing/tiers.ts ===
@@ -0,0 +1,140 @@
+export type Tier = "free" | "pro";
+
+/** The three things that spend a model request. See docs/MONETISATION.md §2. */
+export type GenerationKind = "drop" | "regenerate" | "styled";
+
+export type Entitlements = {
+  tier: Tier;
+  /** Per occasion, per day. null = unlimited. Drops themselves are never metered. */
+  regeneratesPerOccasion: number | null;
+  /**
+   * New pieces per day. null = unlimited.
+   *
+   * A RATE, deliberately, not a closet cap. The closet is the switching cost,
+   * and the generator measurably degrades on a small wardrobe — PR #15 measured
+   * a 21-item closet at 21 combos in winter against 48 in summer — so a total
+   * cap would sell free users a worse stylist rather than fewer features.
+   * Metering the rate smooths cost and gives onboarding a real upgrade moment
+   * ("add your whole wardrobe tonight") while a committed free user still
+   * reaches 100 items in ten days.
+   *
+   * ⚠️ Under review: a 50-item total cap for free may replace or accompany this
+   * (user, 2026-08-04). If it lands, add a separate `closetItems` field rather
+   * than overloading this one — they answer different questions.
+   */
+  uploadsPerDay: number | null;
+  /** "Style an outfit with this" — Pro #2. */
+  styledLooks: boolean;
+  savedOutfits: number | null;
+  /** The Wear Stats SCREEN. The per-item tile on item detail is free. */
+  analytics: boolean;
+  gapAnalysis: boolean;
+  packingMode: boolean;
+};
+
+/**
+ * The tiers, as data. See docs/MONETISATION.md for the reasoning — in short:
+ * meter what costs us money, sell what compounds, and never gate the daily
+ * drop, the share card, or the closet.
+ *
+ * The free ceiling is four occasions × (one drop + one regenerate) = 8
+ * generations a day, about $0.72/month at $0.003 each and nearer $0.20 in
+ * realistic use. **The ceiling is the point** — a free tier needs a worst case
+ * you can survive, and this one does not grow with closet size.
+ */
+export const FREE: Entitlements = {
+  tier: "free",
+  regeneratesPerOccasion: 1,
+  uploadsPerDay: 10,
+  styledLooks: false,
+  savedOutfits: 10,
+  analytics: false,
+  gapAnalysis: false,
+  packingMode: false,
+};
+
+export const PRO: Entitlements = {
+  tier: "pro",
+  regeneratesPerOccasion: null,
+  uploadsPerDay: null,
+  styledLooks: true,
+  savedOutfits: null,
+  analytics: true,
+  gapAnalysis: true,
+  packingMode: true,
+};
+
+// The pure functions live HERE, not in entitlements.ts, so tests can import them
+// without dragging in `server-only` (which does not resolve under jsdom).
+// entitlements.ts re-exports them for app code.
+
+/** Unknown input resolves to free: capabilities fail CLOSED. */
+export function entitlementsFor(tier: unknown): Entitlements {
+  return tier === "pro" ? PRO : FREE;
+}
+
+export type GenerationCheck = {
+  allowed: boolean;
+  /** null = unlimited. Only meaningful for a metered kind. */
+  remaining: number | null;
+  reason?: string;
+};
+
+/**
+ * May this user spend a model request right now?
+ *
+ * `regeneratesUsed` is the count for the ONE occasion being asked about, on the
+ * user's local today — never a global total. The allowance is per occasion so
+ * that regenerating Work cannot exhaust Evening, and so a user is never blocked
+ * on an occasion they have not yet looked at.
+ *
+ * A drop is never metered on any tier: MONETISATION §1 and Decision 4 both say
+ * the daily drop is the product, and rationing it is how nobody discovers the
+ * magic.
+ */
+export function checkGeneration(
+  e: Entitlements,
+  input: { kind: GenerationKind; regeneratesUsed: number },
+): GenerationCheck {
+  if (input.kind === "drop") return { allowed: true, remaining: null };
+
+  if (input.kind === "styled") {
+    return e.styledLooks
+      ? { allowed: true, remaining: null }
+      : {
+          allowed: false,
+          remaining: 0,
+          reason: "Building a look around a piece is a Pro feature.",
+        };
+  }
+
+  if (e.regeneratesPerOccasion == null) return { allowed: true, remaining: null };
+  const remaining = Math.max(0, e.regeneratesPerOccasion - input.regeneratesUsed);
+  return remaining > 0
+    ? { allowed: true, remaining }
+    : {
+        allowed: false,
+        remaining: 0,
+        reason: "You've used today's redo for this occasion. Pro regenerates freely.",
+      };
+}
+
+/**
+ * May this user add another piece right now?
+ *
+ * The wording matters: this is a limit on how fast a wardrobe is added, never
+ * on how large it may be. A message that reads like "your closet is full" would
+ * tell users the opposite of the truth and discourage the very thing that makes
+ * the product better for them.
+ */
+export function checkUploads(e: Entitlements, addedToday: number): GenerationCheck {
+  if (e.uploadsPerDay == null) return { allowed: true, remaining: null };
+  const remaining = Math.max(0, e.uploadsPerDay - addedToday);
+  return remaining > 0
+    ? { allowed: true, remaining }
+    : {
+        allowed: false,
+        remaining: 0,
+        reason: `That's ${e.uploadsPerDay} pieces added today. More tomorrow, or add your whole wardrobe at once with Pro.`,
+      };
+}


