+  const now = new Date();
+  const since = new Date(now.getTime() - 48 * 60 * 60 * 1000).toISOString();
+  const { data } = await supabase
+    .from("items")
+    .select("created_at")
+    .eq("user_id", user.id)
+    .gte("created_at", since);
