294	      location_lon: roundCoord(d.lon),
295	      location_label: d.label,
296	      location_source: d.source,
297	      location_timezone: d.timezone,
298	      location_updated_at: new Date().toISOString(),
299	    })
300	    .eq("id", user.id);
301	}
