303	/**
304	 * The seed for the morning. Cheap on purpose — one profile read, date math, NO
305	 * AI and NO weather — so the client can pick the right occasion before the first
306	 * generate without adding latency.
307	 */
308	export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
309	  const supabase = await createClient();
310	  const {
311	    data: { user },
312	  } = await supabase.auth.getUser();
313	  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };
314	
315	  const { data: profile } = await supabase
316	    .from("profiles")
317	    .select("occasions, location_timezone")
318	    .eq("id", user.id)
319	    .single();
320	
321	  const tz = profile?.location_timezone ?? "UTC";
322	  const occasion = predictOccasion(new Date(), tz, profile?.occasions ?? []);
323	  return { occasion, reason: defaultReason(occasion) };
